#include <bits/stdc++.h>
using namespace std;
typedef long double ld;
int n,k; ld R;
vector<ld> X;
ld Wfun(ld g){
    if(g>=2*R) return M_PI*R*R;
    ld s=g/2;
    return 2*(s*sqrtl(R*R-s*s)+R*R*asinl(s/R));
}
ld brute(){
    ld best=-1e30;
    for(int mask=0; mask<(1<<n); ++mask){
        if(__builtin_popcount(mask)!=k) continue;
        vector<int> idx;
        for(int i=0;i<n;i++) if(mask>>i&1) idx.push_back(i);
        ld s=0; for(int j=1;j<(int)idx.size();j++) s+=Wfun(X[idx[j]]-X[idx[j-1]]);
        best=max(best,s);
    }
    return best;
}
ld greedy(){
    set<int> sel; sel.insert(0); sel.insert(n-1);
    while((int)sel.size()<k){
        ld bestgain=-1e30; int bm=-1;
        for(auto it=sel.begin(); next(it)!=sel.end(); ++it){
            int p=*it, q=*next(it);
            for(int m=p+1;m<q;m++){
                ld g=Wfun(X[m]-X[p])+Wfun(X[q]-X[m])-Wfun(X[q]-X[p]);
                if(g>bestgain){bestgain=g;bm=m;}
            }
        }
        if(bm==-1) break;
        sel.insert(bm);
    }
    ld s=0; for(auto it=sel.begin(); next(it)!=sel.end(); ++it){ s+=Wfun(X[*next(it)]-X[*it]); }
    return s;
}
