// returns f[m] = max sum W gaps over subsets of size m (any endpoints)
vector<ld> allf(){
    vector<ld> f(n+2,-1e30);
    f[1]=0; // single point
    if(n>=2){
        vector<ld> g(n+1,-1e30);
        // subset size m
        // enumerate subsets
        for(int mask=0;mask<(1<<n);mask++){
            int c=__builtin_popcount(mask);
            if(c<1) continue;
            vector<int> idx;
            for(int i=0;i<n;i++) if(mask>>i&1) idx.push_back(i);
            ld s=0; for(int j=1;j<(int)idx.size();j++) s+=Wfun(X[idx[j]]-X[idx[j-1]]);
            f[c]=max(f[c],s);
        }
    }
    return f;
}
int main(){
    srand(999);
    for(int t=0;t<2000;t++){
        n=2+rand()%9;
        R=1+rand()%8;
        set<int> ps; while((int)ps.size()<n) ps.insert(rand()%45);
        X.assign(ps.begin(),ps.end());
        vector<ld> f=allf();
        // check concavity: D_m = f[m]-f[m-1] should be nonincreasing for m>=2 (f[1]=0)
        bool ok=true;
        for(int m=3;m<=n;m++){
