#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const double PI = acos(-1.0);
int n,k,R;
vector<ll> X;
vector<double> Wt;
double Wconst;
double Wfun(double g){
    if(g>=2.0*R) return Wconst;
    double s=g*0.5;
    return 2*(s*sqrt(max(0.0,(double)R*R-s*s))+(double)R*R*asin(s/R));
}
inline double cost(int i,int j){
    ll d=X[i]-X[j];
    if(d>=2*R) return Wconst;
    return Wt[d];
}
struct Cand{int j,l,r;};
pair<double,int> runDP(double lam){
    vector<double> D(n); vector<int> cnt(n);
    D[0]=-lam; cnt[0]=1;
    double V=D[0]; int Vc=1;
    if(n==1) return {V,Vc};
    deque<Cand> dq;
    dq.push_back({0,1,n-1});
    const double EPS=1e-9;
    for(int i=1;i<n;i++){
        while(!dq.empty() && dq.front().r<i) dq.pop_front();
        int j=dq.front().j;
        double best=D[j]+cost(i,j);
        int bc=cnt[j]+1;
        // compare start fresh (value 0, count 1): prefer more count on tie
        if(0.0>best+EPS){ best=0;bc=1; }
        else if(fabs(0.0-best)<=EPS && 1>bc){ best=0;bc=1; }
        D[i]=best-lam; cnt[i]=bc;
        if(D[i]>V+EPS || (fabs(D[i]-V)<=EPS && cnt[i]>Vc)){V=D[i];Vc=cnt[i];}
        int start=i+1;
        if(start>n-1) continue;
        while(true){
            if(dq.empty()){ dq.push_back({i,start,n-1}); break; }
            Cand &last=dq.back();
            if(last.r<start){ dq.pop_back(); continue; }
            int low=max(last.l,start);
            double vi=D[i]+cost(low,i), vj=D[last.j]+cost(low,last.j);
            int ci=cnt[i]+1, cj=cnt[last.j]+1;
            bool better=(vi>vj+EPS)||(fabs(vi-vj)<=EPS && ci>cj);
            if(better){ dq.pop_back(); continue; }
            int lo=low,hi=last.r,ans=-1;
            while(lo<=hi){
                int mid=(lo+hi)/2;
                double a=D[i]+cost(mid,i), b=D[last.j]+cost(mid,last.j);
                int ca=cnt[i]+1, cb=cnt[last.j]+1;
                bool bt=(a>b+EPS)||(fabs(a-b)<=EPS && ca>cb);
                if(bt){ans=mid;hi=mid-1;} else lo=mid+1;
            }
            if(ans==-1){ dq.push_back({i,last.r+1,n-1}); }
            else { dq.back().r=ans-1; dq.push_back({i,ans,n-1}); }
            break;
        }
    }
    return {V,Vc};
}
double solveK(int kk){
    if(kk<=1) return 0.0;
    double lo=0.0, hi=Wfun((double)(X[n-1]-X[0]));
    double bestAns=1e300;
    for(int it=0; it<70; it++){
        double mid=(lo+hi)*0.5;
        auto pr=runDP(mid);
        double cand=pr.first+mid*kk;
        if(cand<bestAns) bestAns=cand;
        if(pr.second>=kk) lo=mid; else hi=mid;
    }
    return bestAns;
}
double brute(int kk){
    double best=-1e30;
    for(int mask=0;mask<(1<<n);mask++){
        if(__builtin_popcount(mask)!=kk) continue;
        vector<int> idx; for(int i=0;i<n;i++) if(mask>>i&1) idx.push_back(i);
        double s=0; for(int j=1;j<(int)idx.size();j++) s+=Wfun((double)(X[idx[j]]-X[idx[j-1]]));
        best=max(best,s);
    }
    return best;
}
int main(){
    srand(2024);
    for(int t=0;t<3000;t++){
        n=2+rand()%9;
        R=1+rand()%8;
        k=1+rand()%n;
        set<int> ps; while((int)ps.size()<n) ps.insert(rand()%45);
        X.assign(ps.begin(),ps.end());
        Wt.assign(2*R+1,0); Wconst=PI*R*R;
        for(int g=1;g<=2*R;g++) Wt[g]=Wfun(g);
        double b=brute(k), a=solveK(k);
        double scal=max(1.0,b);
        if(fabs(a-b)>1e-5*scal){
            printf("MISMATCH n=%d k=%d R=%d a=%.6f b=%.6f\n",n,k,R,a,b);
            for(auto v:X)printf("%lld ",v);printf("\n");
            return 0;
        }
    }
    printf("WQS ALL OK\n");
    return 0;
}

