    return PI*(double)R*R+fk;
}
double brute_full(int kk){
    double best=-1e30;
    for(int mask=0;mask<(1<<n);mask++){
        if(__builtin_popcount(mask)!=kk) continue;
        vector<int> idx; for(int i=0;i<n;i++) if(mask>>i&1) idx.push_back(i);
        double s=PI*(double)R*R; for(int j=1;j<(int)idx.size();j++) s+=Wfun((double)(X[idx[j]]-X[idx[j-1]]));
        best=max(best,s);
    }
    return best;
}
