        for(int g=1;g<=2*R;g++) Wt[g]=Wfun(g);
        for(int kk=1;kk<=n;kk++){
            double a=full_solve(kk), b=brute_full(kk);
            if(fabs(a-b)>1e-5*max(1.0,fabs(b))){
                printf("MISMATCH t=%d n=%d R=%d k=%d a=%.9f b=%.9f\n",t,n,R,kk,a,b);
                for(auto v:X)printf("%lld ",v);printf("\n"); return 0;
            }
        }
    }
    printf("FULL ALL OK\n");
    return 0;
}

